import React from 'react';
import './AboutMe.css'; // Create and add your styles here

const AboutMe = () => (
  <section id="aboutme">
    <div className="container">
      <p>I'm a web developer who loves to create sleek, user-friendly websites. When I'm not coding, you'll find me exploring the latest tech trends or playing video games.</p>
      <p>Graduated from the University of San Jose-Recoletos and had a blast interning at Accenture, where I built cool automation solutions from scratch. Now, I'm ready to take on the world one line of code at a time!</p>
      
    </div>
  </section>
);

export default AboutMe;
